  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Sound, Rhythm and Beat$j$, $j${"readings": [{"title": "Psalm 150 (King James Version)", "url": "/portal/bible/Psalms/150"}], "body": "Music is sound organized in time. Every sound begins when something vibrates, and the vibration travels through the air to the ear. Sound has four basic properties. Pitch is how high or low a sound is. Duration is how long it lasts. Dynamics are how loud or soft it is. Timbre is its tone color, the quality that lets you tell a trumpet from a flute. Psalm 150:6 says, Let every thing that hath breath praise the LORD. Praise ye the LORD.\n\nRhythm is the pattern of long and short sounds and silences in music. The beat is the steady pulse you feel and could tap your foot to. Rhythm moves over the beat, sometimes matching it and sometimes dancing around it. Beats are grouped by the meter. In the time signature 4/4, the top number tells how many beats are in each measure and the bottom number tells which note gets one beat, so 4/4 has four quarter note beats in each measure. In 3/4 there are three beats, the feel of a waltz. In 2/4 there are two, the feel of a march.\n\nNotes show how long a sound lasts. In 4/4, a whole note lasts four beats, a half note two beats, a quarter note one beat and an eighth note half of a beat. A rest is a silence of the same length. Silence is part of music, just as spaces are part of a sentence.\n\nYou can practice by clapping a steady beat, then clapping the rhythm of a familiar hymn or song over it. Notice that the beat stays steady while the rhythm changes.\n\nYour task: (1) Define music and name the four properties of sound. (2) Explain the difference between beat and rhythm. (3) Tell how many beats a whole, half, quarter and eighth note get in 4/4 time.\n\nFlorida standards: MU.912.O.1, MU.912.C.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.O.1, MU.912.C.1", "script": "Welcome to Music Appreciation and Worship Arts. I am Dr. Alex L. Jenkins Sr. Listen, God filled the Bible with songs, and He gave every one of us ears to enjoy them. In this course we learn how music works, where it came from and how to use it to honor Him.\n\nPsalm 150:6 says, Let every thing that hath breath praise the LORD.\n\nNow watch this. Music is sound organized in time. Sound has four properties. Pitch is high or low. Duration is how long. Dynamics are loud or soft. Timbre is the tone color that tells a trumpet from a flute.\n\nLook at rhythm and beat. The beat is the steady pulse, the thing you tap your foot to. Rhythm is the pattern of long and short sounds that moves over the beat. In 4/4 time, there are four beats in each measure. A whole note gets four beats, a half note gets two, a quarter note gets one and an eighth note gets half a beat. A rest is silence of the same length, and silence is part of music.\n\nTry it. Clap a steady beat. Then clap the rhythm of a hymn you know over the beat.\n\nYour task is to define music, name the four properties of sound, explain beat and rhythm, and give the note values in 4/4. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Sound, Rhythm and Beat$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Melody, Pitch and Harmony$j$, $j${"readings": [{"title": "Colossians 3 (King James Version)", "url": "/portal/bible/Colossians/3"}], "body": "A melody is a series of pitches that make a tune. It is the part of a song you hum and remember. Melodies move by steps, which are neighboring notes, and by skips and leaps, which jump over notes. A melody has a contour, the shape it makes as it rises and falls. A phrase is a musical thought, like a sentence, and a cadence is the resting place at the end of a phrase.\n\nPitches are named with the first seven letters of the alphabet, A B C D E F G, and then the pattern repeats. A scale is a set of pitches arranged from low to high. The major scale has eight notes with a pattern of whole steps and half steps: whole, whole, half, whole, whole, whole, half. It sounds bright and settled. A minor scale has a different pattern and often sounds more serious or tender. The first note of a scale is the tonic, or home note, and a tune feels finished when it comes home to it.\n\nHarmony is the sound of two or more pitches at the same time. A chord is three or more pitches sounded together, and the most common is the triad, built from the first, third and fifth notes of a scale. Chords support a melody like a foundation supports a house. Texture describes how the layers fit together. Monophony is a single melody alone. Homophony is a melody with chords beneath it, as in most hymns. Polyphony is two or more melodies at once, as in a round or a fugue.\n\nColossians 3:16 mentions singing with grace in your hearts to the Lord. When a congregation sings in parts, many voices blend into one sound. Notice how the parts support one another.\n\nYour task: (1) Define melody, phrase and cadence. (2) Explain the difference between a scale and a chord. (3) Compare monophony, homophony and polyphony.\n\nFlorida standards: MU.912.O.1, MU.912.C.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.O.1, MU.912.C.1", "script": "Welcome back. Listen, the part of a song you hum in the shower is the melody. Let us look at how it is built.\n\nA melody is a series of pitches that makes a tune. It moves by steps, which are neighboring notes, and by skips and leaps. The shape it makes as it rises and falls is its contour. A phrase is a musical thought, like a sentence, and a cadence is the resting place at the end of it.\n\nNow watch this. Pitches are named A through G, and then the pattern repeats. A scale arranges pitches from low to high. The major scale follows the pattern whole, whole, half, whole, whole, whole, half, and it sounds bright and settled. The first note is the tonic, the home note, and a tune feels finished when it comes home.\n\nLook at harmony. Harmony is two or more pitches at the same time. A chord has three or more, and the most common is the triad, built on the first, third and fifth notes of the scale.\n\nThen there is texture. Monophony is one melody alone. Homophony is a melody with chords under it, like most hymns. Polyphony is two or more melodies at once, like a round.\n\nColossians 3:16 speaks of singing with grace in your hearts to the Lord. Listen for how the parts support one another.\n\nYour task is to define melody, phrase and cadence, explain scales and chords, and compare the three textures. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Melody, Pitch and Harmony$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Tempo, Dynamics and Form$j$, $j${"readings": [{"title": "Psalm 33 (King James Version)", "url": "/portal/bible/Psalms/33"}], "body": "Composers tell performers how to play by using expression marks, and many of them are written in Italian because that language was used by early European composers. Tempo is the speed of the beat. Common tempo words include largo, very slow and broad; adagio, slow; andante, at a walking pace; moderato, moderate; allegro, fast and lively; and presto, very fast. A metronome is a device that clicks at a set number of beats per minute, and the marking beats per minute, written as BPM, gives an exact speed. A ritardando means to slow down gradually, and an accelerando means to speed up.\n\nDynamics are the loudness. Piano, written p, means soft. Forte, written f, means loud. Mezzo means medium, so mezzo piano is medium soft and mezzo forte is medium loud. Pianissimo is very soft and fortissimo is very loud. A crescendo means to get gradually louder and a decrescendo, or diminuendo, means to get gradually softer. Dynamics give music feeling, the way a speaker raises and lowers the voice.\n\nForm is the plan or structure of a piece. Letters show which sections are alike. A B means two different sections. A B A means a section, a contrasting section and a return of the first. Verse and chorus form is common in hymns and songs, where the verses tell the story and the chorus repeats the main message. Theme and variations repeats a theme with changes. A rondo returns to the main theme again and again.\n\nPsalm 33:3 says, Sing unto him a new song; play skilfully with a loud noise. Skill and care in how we shape the music, soft and loud, slow and fast, are part of doing our best for the Lord.\n\nYour task: (1) Match five tempo words to their meanings. (2) Explain piano, forte, crescendo and decrescendo. (3) Describe A B A form and verse and chorus form.\n\nFlorida standards: MU.912.O.1, MU.912.C.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.O.1, MU.912.C.2", "script": "Welcome back. Listen, the same song can feel completely different depending on how it is played. Today we learn the tools composers use.\n\nTempo is the speed of the beat. Largo is very slow. Adagio is slow. Andante is a walking pace. Moderato is moderate. Allegro is fast and lively. Presto is very fast. A ritardando slows down, and an accelerando speeds up. A metronome clicks at a set number of beats per minute.\n\nNow watch this. Dynamics are the loudness. Piano means soft. Forte means loud. Mezzo means medium. Pianissimo is very soft and fortissimo is very loud. A crescendo gets gradually louder, and a decrescendo gets gradually softer. Dynamics give music feeling, the way a speaker raises and lowers the voice.\n\nLook at form, the plan of a piece. A B means two different sections. A B A means a section, a contrast, and a return to the first. Verse and chorus form is common in hymns and songs. The verses tell the story, and the chorus repeats the main message.\n\nPsalm 33:3 says, Sing unto him a new song; play skilfully with a loud noise. Skill and care are part of doing our best for the Lord.\n\nYour task is to match five tempo words, explain the dynamic marks, and describe A B A form and verse and chorus form. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Tempo, Dynamics and Form$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Tone Color and the Instrument Families$j$, $j${"readings": [{"title": "1 Samuel 16 (King James Version)", "url": "/portal/bible/1Samuel/16"}], "body": "Tone color, or timbre, is the special sound of a voice or instrument. Two instruments can play the same note at the same loudness, and you can still tell them apart. Western instruments are grouped into families by how they make sound.\n\nStrings make sound when a string vibrates. The violin, viola, cello and double bass are bowed. The harp and guitar are plucked or strummed. Woodwinds make sound when air is blown across an opening or against a reed. The flute and piccolo use an opening. The clarinet, oboe, bassoon and saxophone use reeds. Brass instruments make sound when the player buzzes the lips into a metal mouthpiece. The trumpet, French horn, trombone and tuba are brass. Percussion instruments make sound when they are struck, shaken or scraped. Some play definite pitches, such as the timpani, xylophone and bells, and some do not, such as the snare drum, cymbals and tambourine. Keyboard instruments, such as the piano and organ, are sometimes grouped separately. Electronic instruments, such as synthesizers, make sound with electronics.\n\nThe human voice is the first instrument. Voices are grouped as soprano, alto, tenor and bass. The Bible names many instruments. Psalm 150 lists the trumpet, psaltery, harp, timbrel, stringed instruments, organs and cymbals. Exodus 15:20 records that Miriam took a timbrel in her hand. First Samuel 16:23 says that David took an harp and played with his hand, and Saul was refreshed.\n\nA symphony orchestra usually has strings, woodwinds, brass and percussion. A choir is a group of singers. A band often has woodwinds, brass and percussion.\n\nYour task: (1) Name the four main instrument families and give two instruments in each. (2) Explain what timbre is. (3) Name the four voice types and three instruments mentioned in Psalm 150.\n\nFlorida standards: MU.912.O.1, MU.912.H.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.O.1, MU.912.H.1", "script": "Welcome back. Listen, God gave us the voice, and then people made instruments to join it. Today we meet the families.\n\nTone color, or timbre, is the special sound of a voice or instrument. Two instruments can play the same note and you can still tell them apart.\n\nNow watch this. Strings make sound when a string vibrates. The violin, viola, cello and double bass are bowed, and the harp and guitar are plucked. Woodwinds use air across an opening or against a reed. The flute, clarinet, oboe, bassoon and saxophone are woodwinds. Brass instruments are played by buzzing the lips into a metal mouthpiece. The trumpet, French horn, trombone and tuba are brass. Percussion instruments are struck, shaken or scraped. The timpani and xylophone play definite pitches. The snare drum and cymbals do not.\n\nLook at the voice. It is the first instrument. Voices are grouped as soprano, alto, tenor and bass.\n\nThe Bible names many instruments. Psalm 150 lists the trumpet, psaltery, harp, timbrel, stringed instruments, organs and cymbals. Miriam took a timbrel in her hand in Exodus 15. David took an harp and played, and Saul was refreshed, in First Samuel 16:23.\n\nYour task is to name the four families with two instruments each, explain timbre, and name the four voice types. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Tone Color and the Instrument Families$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: The Elements of Music$j$, $j${"prompt": "Write a report of at least 250 words on the elements of music. Use complete sentences and label each part. Psalm 150:6 says, Let every thing that hath breath praise the LORD. Praise ye the LORD.\n\nPart 1: Define music and explain the four properties of sound.\nPart 2: Explain beat, rhythm and meter, and give the note values in 4/4 time.\nPart 3: Define melody, harmony, scale and chord, and compare monophony, homophony and polyphony.\nPart 4: Explain tempo and dynamics with at least four examples of Italian terms, and describe two musical forms.\nPart 5: Describe the four instrument families and the four voice types. Listen to one hymn or song this week and describe its tempo, dynamics, form and instruments in a short listening log entry.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: The Elements of Music$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Why God Gave Us Music$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells what kind of music you enjoy most and why it moves you, (2) explains which element of music, such as rhythm, melody, harmony or dynamics, you notice first when you listen, (3) describes a time when music helped you feel peace, joy or strength, and (4) connects your answer to Psalm 150:6, which says, Let every thing that hath breath praise the LORD. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why do people of every culture make music? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Why God Gave Us Music$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Sound, Rhythm and Beat$j$, $j${"questions": [{"q": "Timbre is:", "options": ["How high a sound is", "The tone color of a sound", "The steady pulse", "How loud a sound is"]}, {"q": "The steady pulse you can tap your foot to is the:", "options": ["Beat", "Melody", "Timbre", "Harmony"]}, {"q": "In 4/4 time, a quarter note gets:", "options": ["Two beats", "Four beats", "One beat", "Half a beat"]}, {"q": "A rest in music is:", "options": ["A kind of instrument", "A silence of a set length", "The end of a hymn", "A very loud note"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Sound, Rhythm and Beat$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,2,1}'::int[], array[$j$Timbre lets us tell one instrument or voice from another.$j$,$j$The beat is the steady pulse; rhythm moves over it.$j$,$j$In 4/4 the quarter note is the beat note.$j$,$j$Rests are measured silences that are part of the rhythm.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Sound, Rhythm and Beat$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Melody, Pitch and Harmony$j$, $j${"questions": [{"q": "A melody is:", "options": ["Only the rhythm", "A kind of silence", "Only the chords", "A series of pitches that make a tune"]}, {"q": "The home note of a scale is called the:", "options": ["Texture", "Rest", "Tonic", "Cadence"]}, {"q": "A triad is built from the first, third and fifth notes of a scale and is a kind of:", "options": ["Dynamic", "Rest", "Rhythm", "Chord"]}, {"q": "A melody with chords beneath it, as in most hymns, is called:", "options": ["Silence", "Homophony", "A cadence", "Monophony"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Melody, Pitch and Harmony$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,1}'::int[], array[$j$The melody is the tune you hum and remember.$j$,$j$The tonic is the first note and the sense of home.$j$,$j$A triad is a three note chord.$j$,$j$Homophony is melody supported by chords.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Melody, Pitch and Harmony$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Tempo, Dynamics and Form$j$, $j${"questions": [{"q": "Allegro means:", "options": ["Soft", "Very slow", "Fast and lively", "Getting louder"]}, {"q": "Forte means:", "options": ["Soft", "Loud", "Very slow", "Medium"]}, {"q": "A crescendo means to:", "options": ["Get gradually louder", "Speed up only", "Get gradually softer", "Stop"]}, {"q": "A form in which a section is followed by a contrast and then the first section returns is:", "options": ["Monophony", "Ritardando", "A B C D", "A B A"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Tempo, Dynamics and Form$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,0,3}'::int[], array[$j$Allegro is a fast, lively tempo.$j$,$j$Forte is the dynamic mark for loud.$j$,$j$Crescendo means growing louder.$j$,$j$A B A is a section, a contrast and a return.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Tempo, Dynamics and Form$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Tone Color and the Instrument Families$j$, $j${"questions": [{"q": "A trumpet belongs to the:", "options": ["Woodwind family", "String family", "Percussion family", "Brass family"]}, {"q": "A clarinet is a:", "options": ["String instrument", "Keyboard", "Woodwind", "Brass instrument"]}, {"q": "The four voice types are soprano, alto, tenor and:", "options": ["Timpani", "Treble", "Flute", "Bass"]}, {"q": "According to First Samuel 16:23, David played the:", "options": ["Piano", "Harp", "Saxophone", "Tuba"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Tone Color and the Instrument Families$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,1}'::int[], array[$j$Brass players buzz the lips into a metal mouthpiece.$j$,$j$The clarinet uses a single reed.$j$,$j$SATB are the standard voice parts.$j$,$j$David took an harp and played, and Saul was refreshed.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Tone Color and the Instrument Families$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: The Elements of Music$j$, $j${"questions": [{"q": "Music is best described as:", "options": ["Only singing", "Only noise", "Sound organized in time", "Only instruments"]}, {"q": "Which property of sound tells how high or low it is?", "options": ["Dynamics", "Duration", "Timbre", "Pitch"]}, {"q": "A time signature of 3/4 has:", "options": ["Three beats in each measure", "No beats", "Four beats in each measure", "Two beats in each measure"]}, {"q": "A half note in 4/4 time lasts:", "options": ["Half a beat", "One beat", "Four beats", "Two beats"]}, {"q": "A chord is:", "options": ["A tempo", "A single pitch", "Three or more pitches sounded together", "A kind of rest"]}, {"q": "Polyphony means:", "options": ["Only rhythm", "Only chords", "One melody alone", "Two or more melodies at once"]}, {"q": "Pianissimo means:", "options": ["Very soft", "Very fast", "Very loud", "Very slow"]}, {"q": "A saxophone is a:", "options": ["Woodwind", "Percussion instrument", "String instrument", "Brass instrument"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: The Elements of Music$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,3,2,3,0,0}'::int[], array[$j$Music organizes sound and silence in time.$j$,$j$Pitch is highness or lowness.$j$,$j$The top number is the number of beats in a measure.$j$,$j$A half note is two beats in 4/4.$j$,$j$Chords support melodies.$j$,$j$A round is an example of polyphony.$j$,$j$Pianissimo is very soft.$j$,$j$The saxophone uses a reed, so it is a woodwind.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: The Elements of Music$j$ on conflict (item_id) do nothing;
